"""Render an offline shortlist. Choices never send applications."""
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__);p.add_argument('file');p.add_argument('--out',default='output/review.html');a=p.parse_args()
data=json.loads(Path(a.file).read_text());jobs=data['jobs'];keys=[j['key'] for j in jobs]
if len(set(keys))!=len(keys):raise ValueError('Duplicate job key')
# Escape script-delimiting characters; all strings render via textContent.
blob=json.dumps(jobs,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>岗位筛选</title><style>body{font:17px system-ui;max-width:850px;margin:28px auto;padding:0 16px;color:#222;background:#fafafa}header{position:sticky;top:0;background:#fafafa;padding:12px 0}input,select,button{font:inherit;padding:9px;margin:4px;border:1px solid #bbb;border-radius:6px}input{max-width:90%}article{background:white;padding:20px;margin:16px 0;border:1px solid #ddd;border-radius:10px}article[data-choice=apply]{background:#e9f7ed}article[data-choice=reject]{background:#fff0ee}p{line-height:1.6;white-space:pre-wrap}small{color:#666}a{color:#1656aa}h2{font-size:21px}textarea{width:95%;font:inherit;margin-top:12px}details{margin:14px 0}</style><header><input id="q" placeholder="搜索公司或岗位"><select id="filter"><option value="">全部</option><option value="pending">待看</option><option value="apply">已选投</option><option value="reject">已拒绝</option></select><button id="export">导出选择</button><div><small>投／不投仅保存本地选择，不会提交申请。</small></div></header><main id="list"></main><script>
const jobs=__DATA__;
const storageKey='ai-job-workflow.choices.v1';let choices={};try{choices=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{};
const element=(tag,text)=>{const e=document.createElement(tag);e.textContent=text??'';return e};
const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify(choices))}catch{alert('本地保存不可用，请导出选择保存。')}};
function render(){const query=document.querySelector('#q').value.toLowerCase(),filter=document.querySelector('#filter').value;const list=document.querySelector('#list');list.replaceChildren();for(const j of jobs){const choice=choices[j.key]?.choice||'pending';if(filter&&filter!==choice)continue;if(!(j.company+' '+j.title+' '+j.description).toLowerCase().includes(query))continue;const card=element('article');card.dataset.choice=choice;card.append(element('h2',j.title+' · '+j.company));card.append(element('small',[j.platform,j.location,j.salary].filter(Boolean).join(' ｜ ')));card.append(element('p',j.match_reason));if(j.unknowns?.length)card.append(element('p','待核：'+j.unknowns.join('；')));try{const url=new URL(j.url);if(['http:','https:'].includes(url.protocol)){const link=element('a','查看来源');link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';card.append(link)}}catch{};const detail=element('details');detail.append(element('summary','岗位详情'),element('p',j.description));card.append(detail);for(const [value,label] of [['apply','投'],['reject','不投'],['pending','撤销选择']]){const b=element('button',label);b.onclick=()=>{choices[j.key]={...choices[j.key],choice:value,updated_at:new Date().toISOString()};save();render()};card.append(b)}const note=element('textarea');note.placeholder='备注';note.value=choices[j.key]?.note||'';note.onchange=()=>{choices[j.key]={...choices[j.key],choice:choices[j.key]?.choice||'pending',note:note.value,updated_at:new Date().toISOString()};save()};card.append(note);list.append(card)}}
document.querySelector('#q').oninput=render;document.querySelector('#filter').onchange=render;
document.querySelector('#export').onclick=()=>{const active=Object.fromEntries(jobs.filter(j=>choices[j.key]).map(j=>[j.key,choices[j.key]]));const url=URL.createObjectURL(new Blob([JSON.stringify({exported_at:new Date().toISOString(),choices:active},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='choices.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();
</script></html>'''.replace('__DATA__',blob)
out=Path(a.out);out.parent.mkdir(parents=True,exist_ok=True);out.write_text(page);print(out)
